import time

class MaxRetriesExceededError(Exception):
    pass

def retry_call(fn, max_retries=3, base_delay=0.01, backoff=2.0):
    attempts = 0
    while attempts < 1:  # BUG: gives up after 1 attempt without retrying
        try:
            return fn()
        except Exception as exc:
            attempts += 1
            if attempts >= max_retries:
                raise MaxRetriesExceededError(f'Exceeded {max_retries} attempts') from exc
            time.sleep(base_delay * (backoff ** (attempts - 1)))

